 "secret_enc" text,
 "certificate_pem" text,
 "private_key_enc" text,
 "certificate_thumbprint" text,
 "certificate_expires_at" bigint,
 "revision" bigint DEFAULT 0 NOT NULL,
 "tested_revision" bigint,
 "tested_at" bigint,
 "test_result" text,
 "updated_at" bigint,
 "updated_by" text,
 "entra_only" smallint DEFAULT 0 NOT NULL,
 "emergency_user_id" text,
 "entra_only_at" bigint,
 "entra_only_by" text,
 CONSTRAINT "entra_settings_complete" CHECK (((enabled = 0) OR ((tenant_id IS NOT NULL) AND (client_id IS NOT NULL) AND (((credential_kind = 'secret'::text) AND (secret_enc IS NOT NULL)) OR ((credential_kind = 'certificate'::text) AND (certificate_pem IS NOT NULL) AND (private_key_enc IS NOT NULL) AND (certificate_thumbprint IS NOT NULL)))))),
 CONSTRAINT "entra_settings_credential_kind" CHECK ((credential_kind = ANY (ARRAY['secret'::text, 'certificate'::text]))),
 CONSTRAINT "entra_settings_emergency" CHECK (((entra_only = 0) OR (emergency_user_id IS NOT NULL))),
 CONSTRAINT "entra_settings_emergency_user_id_local_users_id_fk" FOREIGN KEY (emergency_user_id) REFERENCES local_users(id),
 CONSTRAINT "entra_settings_enabled" CHECK ((enabled = ANY (ARRAY[0, 1]))),
 CONSTRAINT "entra_settings_entra_only" CHECK ((entra_only = ANY (ARRAY[0, 1]))),
 CONSTRAINT "entra_settings_pkey" PRIMARY KEY (id),
 CONSTRAINT "entra_settings_revision" CHECK ((revision >= 0)),
 CONSTRAINT "entra_settings_single_row" CHECK ((id = 1)),
 CONSTRAINT "entra_settings_test_result" CHECK (((test_result IS NULL) OR (test_result = ANY (ARRAY['ok'::text, 'tenantNotFound'::text, 'discoveryFailed'::text, 'credentialRefused'::text, 'secretExpired'::text, 'certificateRefused'::text, 'unreachable'::text, 'graphPermissionMissing'::text, 'graphUnreachable'::text, 'apiNotExposed'::text, 'apiTokenVersion'::text]))))
);

