 CONSTRAINT "entra_sign_in_flows_confirm_fields" CHECK ((((purpose = 'confirm'::text) AND (user_id IS NOT NULL) AND (primary_hash IS NOT NULL) AND (claim_hash IS NOT NULL) AND (settings_revision IS NOT NULL)) OR ((purpose = 'sign-in'::text) AND (user_id IS NULL) AND (primary_hash IS NULL) AND (claim_hash IS NULL) AND (settings_revision IS NULL) AND (confirmed_at IS NULL) AND (outcome IS NULL)))),
 CONSTRAINT "entra_sign_in_flows_grant" CHECK (((grant_hash IS NULL) OR (purpose = 'sign-in'::text))),
 CONSTRAINT "entra_sign_in_flows_outcome" CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['cancelled'::text, 'expired'::text, 'mfaMissing'::text, 'apiSetupMissing'::text, 'wrongTenant'::text, 'wrongAccount'::text, 'staleSignIn'::text, 'accountDisabled'::text, 'tokenRejected'::text, 'unavailable'::text, 'notConfigured'::text])))),
 CONSTRAINT "entra_sign_in_flows_pkey" PRIMARY KEY (state_hash),
 CONSTRAINT "entra_sign_in_flows_purpose" CHECK ((purpose = ANY (ARRAY['sign-in'::text, 'confirm'::text]))),
 CONSTRAINT "entra_sign_in_flows_result" CHECK (((confirmed_at IS NULL) OR (outcome IS NULL))),
