 CONSTRAINT "local_users_entra_identity" CHECK ((((identity_source = 'local'::text) AND (entra_tenant_id IS NULL) AND (entra_object_id IS NULL)) OR ((identity_source = 'entra'::text) AND (entra_tenant_id IS NOT NULL) AND (entra_object_id IS NOT NULL) AND (password_hash IS NULL) AND (must_reset = 0) AND (auth_principal = ((('entra:'::text || entra_tenant_id) || ':'::text) || entra_object_id))))),
 CONSTRAINT "local_users_identity_source" CHECK ((identity_source = ANY (ARRAY['local'::text, 'entra'::text]))),
