 "principal" text NOT NULL,
 "expires_at" bigint NOT NULL,
 CONSTRAINT "mfa_proofs_pkey" PRIMARY KEY (token_hash)
);

CREATE TABLE "mfa_sessions" (
 "token_hash" text NOT NULL,
 "principal" text NOT NULL,
 "created_at" bigint NOT NULL,
 "last_activity" bigint NOT NULL,
 "idle_expires_at" bigint NOT NULL,
 "expires_at" bigint NOT NULL,
 "passkey_id" text,
 CONSTRAINT "mfa_sessions_pkey" PRIMARY KEY (token_hash)
);

CREATE TABLE "notification_channels" (
 "id" text NOT NULL,
 "type" text NOT NULL,
 "name" text NOT NULL,
 "enabled" smallint NOT NULL,
 "language" text DEFAULT 'en'::text NOT NULL,
 "config" text NOT NULL,
 "secret" text,
 "target_hint" text NOT NULL,
 "revision" bigint NOT NULL,
 "created_at" bigint NOT NULL,
 "created_by" text NOT NULL,
 "updated_at" bigint NOT NULL,
 "updated_by" text NOT NULL,
 CONSTRAINT "notification_channels_config_check" CHECK ((config IS JSON OBJECT)),
 CONSTRAINT "notification_channels_enabled_check" CHECK ((enabled = ANY (ARRAY[0, 1]))),
 CONSTRAINT "notification_channels_language_check" CHECK ((language = ANY (ARRAY['en'::text, 'de'::text]))),
 CONSTRAINT "notification_channels_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 80))),
 CONSTRAINT "notification_channels_pkey" PRIMARY KEY (id),
 CONSTRAINT "notification_channels_revision_check" CHECK ((revision >= 0)),
 CONSTRAINT "notification_channels_type_check" CHECK ((type = ANY (ARRAY['smtp'::text, 'teams'::text, 'discord'::text, 'webhook'::text])))
);

CREATE TABLE "notification_deliveries" (
 "id" text NOT NULL,
 "event_id" text NOT NULL,
 "channel_id" text,
 "channel_name" text NOT NULL,
 "channel_type" text NOT NULL,
 "target_hint" text NOT NULL,
 "message_id" text,
 "status" text NOT NULL,
 "attempts" integer NOT NULL,
 "next_attempt_at" bigint,
 "sent_at" bigint,
 "last_attempt_at" bigint,
 "error_key" text,
 "error_params" text,
 "claimed_by" text,
 "claimed_at" bigint,
 "recovered" smallint DEFAULT 0 NOT NULL,
 "created_at" bigint NOT NULL,
 "recipients" text,
 CONSTRAINT "notification_deliveries_attempts_check" CHECK ((((attempts >= 0) AND (attempts <= 10)) AND (recovered = ANY (ARRAY[0, 1])))),
 CONSTRAINT "notification_deliveries_channel_id_notification_channels_id_fk" FOREIGN KEY (channel_id) REFERENCES notification_channels(id) ON DELETE SET NULL,
 CONSTRAINT "notification_deliveries_error_params_check" CHECK (((error_params IS NULL) OR (error_params IS JSON OBJECT))),
 CONSTRAINT "notification_deliveries_event_id_notification_events_id_fk" FOREIGN KEY (event_id) REFERENCES notification_events(id) ON DELETE CASCADE,
 CONSTRAINT "notification_deliveries_pkey" PRIMARY KEY (id),
 CONSTRAINT "notification_deliveries_recipients_check" CHECK (((recipients IS NULL) OR (recipients IS JSON ARRAY))),
 CONSTRAINT "notification_deliveries_sending_check" CHECK (((status = 'sending'::text) = (claimed_by IS NOT NULL))),
 CONSTRAINT "notification_deliveries_sent_check" CHECK (((status = 'sent'::text) = (sent_at IS NOT NULL))),
 CONSTRAINT "notification_deliveries_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'sending'::text, 'sent'::text, 'failed'::text]))),
 CONSTRAINT "notification_deliveries_type_check" CHECK ((channel_type = ANY (ARRAY['smtp'::text, 'teams'::text, 'discord'::text, 'webhook'::text])))
);

CREATE TABLE "notification_dispatch" (
 "id" smallint NOT NULL,
 "last_started_at" bigint,
 CONSTRAINT "notification_dispatch_pkey" PRIMARY KEY (id),
 CONSTRAINT "notification_dispatch_single_row" CHECK ((id = 1))
);

CREATE TABLE "notification_events" (
 "id" text NOT NULL,
 "alert_id" text,
 "server_id" text,
 "customer_id" text,
 "kind" text NOT NULL,
 "level" text,
 "rule_id" text,
 "key" text,
 "value" double precision,
 "threshold" integer,
 "close_reason" text,
 "occurred_at" bigint NOT NULL,
 "status" text NOT NULL,
 "suppressed_reason" text,
 "routed_at" bigint,
 "security_alarm_id" text,
 CONSTRAINT "notification_events_alarm_check" CHECK ((((kind = ANY (ARRAY['test'::text, 'emergency'::text])) = (alert_id IS NULL)) AND ((kind = ANY (ARRAY['test'::text, 'emergency'::text])) = (server_id IS NULL)) AND ((kind = 'test'::text) = (level IS NULL)) AND ((kind <> 'emergency'::text) OR (level = 'critical'::text)))),
 CONSTRAINT "notification_events_close_reason_check" CHECK ((((kind = 'close'::text) = (close_reason IS NOT NULL)) AND ((close_reason IS NULL) OR (close_reason = ANY (ARRAY['recovered'::text, 'rule-off'::text, 'no-data'::text]))))),
 CONSTRAINT "notification_events_emergency_check" CHECK (((kind = 'emergency'::text) = (security_alarm_id IS NOT NULL))),
 CONSTRAINT "notification_events_kind_check" CHECK ((kind = ANY (ARRAY['open'::text, 'escalate'::text, 'close'::text, 'test'::text, 'emergency'::text]))),
 CONSTRAINT "notification_events_level_check" CHECK (((level IS NULL) OR (level = ANY (ARRAY['info'::text, 'warning'::text, 'critical'::text])))),
 CONSTRAINT "notification_events_pkey" PRIMARY KEY (id),
 CONSTRAINT "notification_events_security_alarm_id_security_alarms_id_fk" FOREIGN KEY (security_alarm_id) REFERENCES security_alarms(id),
 CONSTRAINT "notification_events_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'routed'::text, 'suppressed'::text]))),
 CONSTRAINT "notification_events_suppressed_check" CHECK ((((status = 'suppressed'::text) = (suppressed_reason IS NOT NULL)) AND ((suppressed_reason IS NULL) OR (suppressed_reason = ANY (ARRAY['muted'::text, 'maintenance-window'::text, 'not-notified'::text, 'no-rule'::text, 'no-recipient'::text])))))
);

CREATE TABLE "notification_rules" (
 "id" text NOT NULL,
 "scope_type" text NOT NULL,
 "scope_id" text NOT NULL,
 "channel_id" text NOT NULL,
 "levels" text NOT NULL,
 "on_open" smallint NOT NULL,
 "on_close" smallint NOT NULL,
 "on_escalate" smallint NOT NULL,
 "enabled" smallint NOT NULL,
 "revision" bigint NOT NULL,
 "created_at" bigint NOT NULL,
 "created_by" text NOT NULL,
 "updated_at" bigint NOT NULL,
 "updated_by" text NOT NULL,
 CONSTRAINT "notification_rules_channel_id_notification_channels_id_fk" FOREIGN KEY (channel_id) REFERENCES notification_channels(id) ON DELETE CASCADE,
 CONSTRAINT "notification_rules_flags_check" CHECK (((on_open = ANY (ARRAY[0, 1])) AND (on_close = ANY (ARRAY[0, 1])) AND (on_escalate = ANY (ARRAY[0, 1])) AND (enabled = ANY (ARRAY[0, 1])) AND (((on_open + on_close) + on_escalate) >= 1))),
 CONSTRAINT "notification_rules_levels_check" CHECK ((levels = ANY (ARRAY['["info"]'::text, '["warning"]'::text, '["critical"]'::text, '["info","warning"]'::text, '["info","critical"]'::text, '["warning","critical"]'::text, '["info","warning","critical"]'::text]))),
 CONSTRAINT "notification_rules_pkey" PRIMARY KEY (id),
 CONSTRAINT "notification_rules_revision_check" CHECK ((revision >= 0)),
 CONSTRAINT "notification_rules_scope_channel_key" UNIQUE (scope_type, scope_id, channel_id),
 CONSTRAINT "notification_rules_scope_id_check" CHECK (((scope_type = 'all'::text) = (scope_id = '*'::text))),
 CONSTRAINT "notification_rules_scope_type_check" CHECK ((scope_type = ANY (ARRAY['all'::text, 'customer'::text, 'group'::text])))
);

CREATE TABLE "notification_test_limits" (
 "principal" text NOT NULL,
 "attempts" integer NOT NULL,
 "window_at" bigint NOT NULL,
 CONSTRAINT "notification_test_limits_pkey" PRIMARY KEY (principal)
);

CREATE TABLE "os_esu_overrides" (
 "id" text NOT NULL,
 "scope_type" text NOT NULL,
 "scope_id" text NOT NULL,
