 CONSTRAINT "os_esu_overrides_pkey" PRIMARY KEY (id),
 CONSTRAINT "os_esu_overrides_scope_type_check" CHECK ((scope_type = ANY (ARRAY['customer'::text, 'group'::text, 'device'::text]))),
 CONSTRAINT "os_esu_overrides_scope_type_scope_id_key" UNIQUE (scope_type, scope_id),
 CONSTRAINT "os_esu_overrides_until_check" CHECK ((until ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'::text))
);

CREATE TABLE "passkey_challenges" (
 "id" text NOT NULL,
