);

CREATE TABLE "plugin_ad_sessions" (
 "id" text NOT NULL,
 "principal" text NOT NULL,
 "session_hash" text NOT NULL,
 "state" text NOT NULL,
 "source" text NOT NULL,
 "job_id" text,
 "server_id" text,
 "directory_kind" text NOT NULL,
 "directory_name" text NOT NULL,
 "directory_sid" text NOT NULL,
 "user_sid" text,
 "account" text,
 "upn" text,
 "created_at" bigint NOT NULL,
 "verified_at" bigint,
 "expires_at" bigint,
 CONSTRAINT "plugin_ad_sessions_active_check" CHECK (((state <> 'active'::text) OR ((user_sid IS NOT NULL) AND (verified_at IS NOT NULL)))),
 CONSTRAINT "plugin_ad_sessions_directory_kind_check" CHECK ((directory_kind = ANY (ARRAY['domain'::text, 'local'::text]))),
 CONSTRAINT "plugin_ad_sessions_pkey" PRIMARY KEY (id),
 CONSTRAINT "plugin_ad_sessions_session_hash_mfa_sessions_token_hash_fk" FOREIGN KEY (session_hash) REFERENCES mfa_sessions(token_hash) ON DELETE CASCADE,
 CONSTRAINT "plugin_ad_sessions_source_check" CHECK ((source = ANY (ARRAY['password'::text, 'entra'::text]))),
 CONSTRAINT "plugin_ad_sessions_state_check" CHECK ((state = ANY (ARRAY['pending'::text, 'active'::text])))
);

CREATE TABLE "plugin_release_files" (
