 CONSTRAINT "plugin_release_files_chunks_check" CHECK ((chunks IS JSON ARRAY)),
 CONSTRAINT "plugin_release_files_release_id_path_pk" PRIMARY KEY (release_id, path),
 CONSTRAINT "plugin_release_files_release_id_plugin_releases_id_fk" FOREIGN KEY (release_id) REFERENCES plugin_releases(id),
 CONSTRAINT "plugin_release_files_sha256_check" CHECK ((sha256 ~ '^[a-f0-9]{64}$'::text)),
