 CONSTRAINT "plugin_releases_name_version_key" UNIQUE (name, version),
 CONSTRAINT "plugin_releases_pkey" PRIMARY KEY (id),
 CONSTRAINT "plugin_releases_state_check" CHECK ((state = ANY (ARRAY['active'::text, 'disabled'::text])))
);

