 CONSTRAINT "rdp_receipts_session_id_direction_seq_pk" PRIMARY KEY (session_id, direction, seq),
 CONSTRAINT "rdp_receipts_session_id_rdp_sessions_id_fk" FOREIGN KEY (session_id) REFERENCES rdp_sessions(id) ON DELETE CASCADE
);

