 CONSTRAINT "rdp_rtc_offer_size" CHECK (((length(offer) >= 24) AND (length(offer) <= 65536))),
 CONSTRAINT "rdp_rtc_sessions_pkey" PRIMARY KEY (session_id),
 CONSTRAINT "rdp_rtc_sessions_session_id_rdp_sessions_id_fk" FOREIGN KEY (session_id) REFERENCES rdp_sessions(id) ON DELETE CASCADE
);

CREATE TABLE "rdp_sessions" (
 "id" text NOT NULL,
 "server_id" text NOT NULL,
 "principal" text NOT NULL,
 "mfa_hash" text NOT NULL,
 "state" text DEFAULT 'opening'::text NOT NULL,
 "key_envelope" text,
 "key_hash" text NOT NULL,
 "input_seq" bigint DEFAULT 0 NOT NULL,
 "input_ack" bigint DEFAULT 0 NOT NULL,
 "output_seq" bigint DEFAULT 0 NOT NULL,
 "output_ack" bigint DEFAULT 0 NOT NULL,
 "created_at" bigint NOT NULL,
 "last_presence" bigint NOT NULL,
 "expires_at" bigint NOT NULL,
 "error" text,
 "transport" text DEFAULT 'mailbox'::text NOT NULL,
 CONSTRAINT "rdp_session_ack" CHECK (((input_ack >= 0) AND (input_ack <= input_seq) AND (output_ack >= 0) AND (output_ack <= output_seq))),
 CONSTRAINT "rdp_session_state" CHECK ((state = ANY (ARRAY['opening'::text, 'open'::text, 'closed'::text, 'error'::text]))),
 CONSTRAINT "rdp_sessions_pkey" PRIMARY KEY (id),
 CONSTRAINT "rdp_sessions_server_id_servers_id_fk" FOREIGN KEY (server_id) REFERENCES servers(id)
);

