 "scope_id" text NOT NULL,
 "created_at" bigint NOT NULL,
 "created_by" text NOT NULL,
 "source" text DEFAULT 'manual'::text NOT NULL,
 CONSTRAINT "role_assignment_entra_user" CHECK (((source = 'manual'::text) OR ((principal_type = 'user'::text) AND (scope_type = ANY (ARRAY['global'::text, 'devicegroup'::text]))))),
 CONSTRAINT "role_assignment_global" CHECK (((scope_type <> 'global'::text) OR (scope_id = '*'::text))),
 CONSTRAINT "role_assignment_principal_type" CHECK ((principal_type = ANY (ARRAY['user'::text, 'group'::text]))),
 CONSTRAINT "role_assignment_scope_type" CHECK ((scope_type = ANY (ARRAY['global'::text, 'devicegroup'::text, 'device'::text]))),
 CONSTRAINT "role_assignment_source" CHECK ((source = ANY (ARRAY['manual'::text, 'entra'::text]))),
 CONSTRAINT "role_assignments_pkey" PRIMARY KEY (id),
 CONSTRAINT "role_assignments_role_id_rbac_roles_id_fk" FOREIGN KEY (role_id) REFERENCES rbac_roles(id)
);

