 "last_success_at" bigint,
 "last_error" text,
 "revision" bigint DEFAULT 0 NOT NULL,
 CONSTRAINT "usage_data_consent" CHECK ((consent = ANY (ARRAY[(0)::bigint, (1)::bigint]))),
 CONSTRAINT "usage_data_instance_id" CHECK (((length(instance_id) = 32) AND (instance_id ~ '^[0-9a-f]*$'::text))),
