 CONSTRAINT "usage_data_pkey" PRIMARY KEY (id),
 CONSTRAINT "usage_data_single_row" CHECK ((id = 1))
);

CREATE TABLE "user_group_members" (
 "group_id" text NOT NULL,
 "user_id" text NOT NULL,
 CONSTRAINT "user_group_members_group_id_user_groups_id_fk" FOREIGN KEY (group_id) REFERENCES user_groups(id) ON DELETE CASCADE,
 CONSTRAINT "user_group_members_group_id_user_id_pk" PRIMARY KEY (group_id, user_id),
 CONSTRAINT "user_group_members_user_id_local_users_id_fk" FOREIGN KEY (user_id) REFERENCES local_users(id) ON DELETE CASCADE
);

CREATE TABLE "user_groups" (
 "id" text NOT NULL,
 "name" text NOT NULL,
 "description" text DEFAULT ''::text NOT NULL,
 "enabled" bigint DEFAULT 1 NOT NULL,
 "created_at" bigint NOT NULL,
 CONSTRAINT "user_groups_pkey" PRIMARY KEY (id)
);

CREATE TABLE "vulnerabilities" (
 "cve_id" text NOT NULL,
 "published" bigint,
 "last_modified" bigint,
 "severity" text NOT NULL,
 "score" double precision,
 "vector" text,
 "summary" text NOT NULL,
 "known_exploited" smallint DEFAULT 0 NOT NULL,
 "fetched_at" bigint NOT NULL,
 "source" text DEFAULT 'nvd'::text NOT NULL,
 CONSTRAINT "vulnerabilities_id_check" CHECK ((cve_id ~ '^CVE-[0-9]{4}-[0-9]{4,}$'::text)),
 CONSTRAINT "vulnerabilities_known_exploited_check" CHECK ((known_exploited = ANY (ARRAY[0, 1]))),
 CONSTRAINT "vulnerabilities_pkey" PRIMARY KEY (cve_id),
 CONSTRAINT "vulnerabilities_severity_check" CHECK ((severity = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text, 'none'::text, 'unknown'::text]))),
 CONSTRAINT "vulnerabilities_source_check" CHECK ((source = ANY (ARRAY['nvd'::text, 'cvelist'::text])))
);

CREATE TABLE "vulnerability_cvelist_products" (
 "product_id" text NOT NULL,
 "cpe" text NOT NULL,
 "synced_at" bigint,
 "full_synced_at" bigint,
 "cve_count" bigint DEFAULT 0 NOT NULL,
 CONSTRAINT "vulnerability_cvelist_products_pkey" PRIMARY KEY (product_id)
);

CREATE TABLE "vulnerability_products" (
 "product_id" text NOT NULL,
 "cpe" text NOT NULL,
 "synced_at" bigint,
 "full_synced_at" bigint,
 "cve_count" bigint DEFAULT 0 NOT NULL,
 "rules_version" integer DEFAULT 0 NOT NULL,
 CONSTRAINT "vulnerability_products_pkey" PRIMARY KEY (product_id)
);

CREATE TABLE "vulnerability_ranges" (
 "cve_id" text NOT NULL,
 "product_id" text NOT NULL,
 "version_exact" text,
 "version_start" text,
 "start_inclusive" smallint DEFAULT 0 NOT NULL,
 "version_end" text,
 "end_inclusive" smallint DEFAULT 0 NOT NULL,
 "synced_at" bigint NOT NULL,
 "source" text DEFAULT 'nvd'::text NOT NULL,
 CONSTRAINT "vulnerability_ranges_cve_id_vulnerabilities_cve_id_fk" FOREIGN KEY (cve_id) REFERENCES vulnerabilities(cve_id) ON DELETE CASCADE,
 CONSTRAINT "vulnerability_ranges_flags_check" CHECK (((start_inclusive = ANY (ARRAY[0, 1])) AND (end_inclusive = ANY (ARRAY[0, 1])))),
 CONSTRAINT "vulnerability_ranges_source_check" CHECK ((source = ANY (ARRAY['nvd'::text, 'cvelist'::text])))
);

CREATE TABLE "vulnerability_settings" (
 "id" smallint NOT NULL,
 "enabled" smallint DEFAULT 0 NOT NULL,
 "api_key" text,
 "revision" bigint DEFAULT 0 NOT NULL,
 "updated_at" bigint,
 "updated_by" text,
 "cvelist_enabled" smallint DEFAULT 0 NOT NULL,
 CONSTRAINT "vulnerability_settings_cvelist_enabled_check" CHECK ((cvelist_enabled = ANY (ARRAY[0, 1]))),
 CONSTRAINT "vulnerability_settings_enabled_check" CHECK ((enabled = ANY (ARRAY[0, 1]))),
 CONSTRAINT "vulnerability_settings_pkey" PRIMARY KEY (id),
 CONSTRAINT "vulnerability_settings_revision_check" CHECK ((revision >= 0)),
 CONSTRAINT "vulnerability_settings_single_row" CHECK ((id = 1))
);

CREATE TABLE "vulnerability_sync" (
 "id" smallint NOT NULL,
 "lease_holder" text,
 "lease_until" bigint,
 "requested_at" bigint,
 "last_started_at" bigint,
 "last_finished_at" bigint,
 "last_success_at" bigint,
 "last_status" text,
 "last_error" text,
 "cvelist_last_finished_at" bigint,
 "cvelist_last_success_at" bigint,
 "cvelist_last_status" text,
 "cvelist_last_error" text,
 CONSTRAINT "vulnerability_sync_cvelist_status_check" CHECK (((cvelist_last_status IS NULL) OR (cvelist_last_status = ANY (ARRAY['ok'::text, 'failed'::text])))),
 CONSTRAINT "vulnerability_sync_pkey" PRIMARY KEY (id),
 CONSTRAINT "vulnerability_sync_single_row" CHECK ((id = 1)),
 CONSTRAINT "vulnerability_sync_status_check" CHECK (((last_status IS NULL) OR (last_status = ANY (ARRAY['ok'::text, 'failed'::text]))))
);

