CREATE OR REPLACE FUNCTION public.agent_integrity_removed_device()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 DELETE FROM agent_integrity_events WHERE server_id=NEW.id;
 RETURN NULL;
END $function$;

