CREATE OR REPLACE FUNCTION public.audit_insert_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id) THEN RAISE EXCEPTION 'customer-missing'; END IF;
 IF NEW.server_id IS NOT NULL AND EXISTS(SELECT 1 FROM servers WHERE id=NEW.server_id AND customer_id IS DISTINCT FROM NEW.customer_id) THEN RAISE EXCEPTION 'customer-mismatch'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.audit_insert_device_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 NEW.customer_id := (SELECT servers.customer_id FROM servers WHERE servers.id=NEW.server_id);
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.audit_update_customer_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'audit-customer-immutable';
END $function$;

