CREATE OR REPLACE FUNCTION public.automation_scope_assignments_insert_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM automation_templates scope_template WHERE scope_template.id=NEW.template_id AND scope_template.customer_id IS NOT NULL AND NOT (
  (NEW.scope_type='group' AND EXISTS(SELECT 1 FROM device_groups target WHERE target.id=NEW.scope_id AND target.customer_id=scope_template.customer_id))
  OR (NEW.scope_type='device' AND EXISTS(SELECT 1 FROM servers target WHERE target.id=NEW.scope_id AND target.customer_id=scope_template.customer_id)))) THEN
  RAISE EXCEPTION 'customer-catalog-mismatch';
 END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.automation_scope_assignments_update_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM automation_templates scope_template WHERE scope_template.id=NEW.template_id AND scope_template.customer_id IS NOT NULL AND NOT (
  (NEW.scope_type='group' AND EXISTS(SELECT 1 FROM device_groups target WHERE target.id=NEW.scope_id AND target.customer_id=scope_template.customer_id))
  OR (NEW.scope_type='device' AND EXISTS(SELECT 1 FROM servers target WHERE target.id=NEW.scope_id AND target.customer_id=scope_template.customer_id)))) THEN
  RAISE EXCEPTION 'customer-catalog-mismatch';
 END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.automation_templates_insert_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id) THEN RAISE EXCEPTION 'customer-missing'; END IF;
 IF EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id AND status='disabled') THEN RAISE EXCEPTION 'customer-disabled'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.automation_templates_insert_runbook_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM runbooks template_runbook WHERE template_runbook.id=NEW.slot AND template_runbook.customer_id IS NOT NULL AND template_runbook.customer_id IS DISTINCT FROM NEW.customer_id) THEN
  RAISE EXCEPTION 'customer-catalog-mismatch';
 END IF;
 RETURN NEW;
END $function$;

