 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'customer-catalog-immutable';
END $function$;

CREATE OR REPLACE FUNCTION public.automation_templates_update_runbook_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM runbooks template_runbook WHERE template_runbook.id=NEW.slot AND template_runbook.customer_id IS NOT NULL AND template_runbook.customer_id IS DISTINCT FROM NEW.customer_id) THEN
  RAISE EXCEPTION 'customer-catalog-mismatch';
 END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.customer_assignments_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id) THEN RAISE EXCEPTION 'customer-missing'; END IF;
 IF (NEW.principal_type='user' AND NOT EXISTS(SELECT 1 FROM local_users WHERE id=NEW.principal_id)) OR (NEW.principal_type='group' AND NOT EXISTS(SELECT 1 FROM user_groups WHERE id=NEW.principal_id)) THEN RAISE EXCEPTION 'customer-assignment-subject-missing'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.customer_assignments_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id) THEN RAISE EXCEPTION 'customer-missing'; END IF;
 IF (NEW.principal_type='user' AND NOT EXISTS(SELECT 1 FROM local_users WHERE id=NEW.principal_id)) OR (NEW.principal_type='group' AND NOT EXISTS(SELECT 1 FROM user_groups WHERE id=NEW.principal_id)) THEN RAISE EXCEPTION 'customer-assignment-subject-missing'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.customer_installers_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id) THEN RAISE EXCEPTION 'customer-missing'; END IF;
 IF EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id AND status='disabled') THEN RAISE EXCEPTION 'customer-disabled'; END IF;
 IF NEW.group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM device_groups WHERE id=NEW.group_id AND customer_id=NEW.customer_id) THEN RAISE EXCEPTION 'customer-installer-group-mismatch'; END IF;
 RETURN NEW;
END $function$;

