CREATE OR REPLACE FUNCTION public.device_group_members_insert_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 -- A missing device or group gives NULL and raises nothing here, as before.
 IF (SELECT customer_id FROM servers WHERE id=NEW.server_id)<>(SELECT customer_id FROM device_groups WHERE id=NEW.group_id) THEN RAISE EXCEPTION 'customer-mismatch'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_group_members_insert_path()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS (
  SELECT 1 FROM device_group_members existing
  JOIN device_group_ancestors path ON path.depth>0 AND (
   (path.group_id=NEW.group_id AND path.ancestor_id=existing.group_id) OR
   (path.group_id=existing.group_id AND path.ancestor_id=NEW.group_id)
  )
  WHERE existing.server_id=NEW.server_id
 ) THEN RAISE EXCEPTION 'device-group-membership-path-conflict'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_group_members_insert_target()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM servers WHERE id=NEW.server_id) OR NOT EXISTS(SELECT 1 FROM device_groups WHERE id=NEW.group_id) THEN RAISE EXCEPTION 'device-group-member-missing'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_group_members_update_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (SELECT customer_id FROM servers WHERE id=NEW.server_id)<>(SELECT customer_id FROM device_groups WHERE id=NEW.group_id) THEN RAISE EXCEPTION 'customer-mismatch'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_group_members_update_path()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS (
  SELECT 1 FROM device_group_members existing
  JOIN device_group_ancestors path ON path.depth>0 AND (
   (path.group_id=NEW.group_id AND path.ancestor_id=existing.group_id) OR
   (path.group_id=existing.group_id AND path.ancestor_id=NEW.group_id)
  )
  WHERE existing.server_id=NEW.server_id
   AND NOT (existing.server_id=OLD.server_id AND existing.group_id=OLD.group_id)
 ) THEN RAISE EXCEPTION 'device-group-membership-path-conflict'; END IF;
 RETURN NEW;
END $function$;

