CREATE OR REPLACE FUNCTION public.device_groups_insert_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id) THEN RAISE EXCEPTION 'customer-missing'; END IF;
 IF NEW.parent_id IS NOT NULL AND EXISTS(SELECT 1 FROM device_groups parent WHERE parent.id=NEW.parent_id AND parent.customer_id<>NEW.customer_id) THEN RAISE EXCEPTION 'customer-mismatch'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_groups_insert_customer_disabled()
