 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_groups_insert_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM device_groups WHERE id=NEW.parent_id) THEN RAISE EXCEPTION 'device-group-parent-missing'; END IF;
 IF NEW.parent_id=NEW.id THEN RAISE EXCEPTION 'device-group-cycle'; END IF;
 IF NEW.parent_id IS NOT NULL AND (SELECT coalesce(max(depth),0) FROM device_group_ancestors WHERE group_id=NEW.parent_id)>=4 THEN RAISE EXCEPTION 'device-group-depth-limit'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_groups_insert_paths()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 INSERT INTO device_group_paths(group_id,ancestor_id,depth) VALUES(NEW.id,NEW.id,0);
 INSERT INTO device_group_paths(group_id,ancestor_id,depth)
  SELECT NEW.id,ancestor_id,depth+1 FROM device_group_paths WHERE group_id=NEW.parent_id;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.device_groups_update_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id) THEN RAISE EXCEPTION 'customer-missing'; END IF;
 IF NEW.parent_id IS NOT NULL AND EXISTS(SELECT 1 FROM device_groups parent WHERE parent.id=NEW.parent_id AND parent.customer_id<>NEW.customer_id) THEN RAISE EXCEPTION 'customer-mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM device_groups child WHERE child.parent_id=OLD.id AND child.id<>OLD.id AND child.customer_id<>NEW.customer_id) THEN RAISE EXCEPTION 'customer-mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM device_group_members member JOIN servers device ON device.id=member.server_id WHERE member.group_id=OLD.id AND device.customer_id<>NEW.customer_id) THEN RAISE EXCEPTION 'customer-mismatch'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_groups_update_customer_catalog()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM role_assignments moved_assignment JOIN rbac_roles moved_role ON moved_role.id=moved_assignment.role_id WHERE moved_assignment.scope_type='devicegroup' AND moved_assignment.scope_id=OLD.id AND moved_role.customer_id IS NOT NULL AND moved_role.customer_id IS DISTINCT FROM NEW.customer_id)
  OR EXISTS(SELECT 1 FROM automation_scope_assignments moved_scope JOIN automation_templates moved_template ON moved_template.id=moved_scope.template_id WHERE moved_scope.scope_type='group' AND moved_scope.scope_id=OLD.id AND moved_template.customer_id IS NOT NULL AND moved_template.customer_id IS DISTINCT FROM NEW.customer_id) THEN
  RAISE EXCEPTION 'customer-mismatch';
 END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_groups_update_customer_disabled()
