 IF EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id AND status='disabled') THEN RAISE EXCEPTION 'customer-disabled'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_groups_update_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM device_groups WHERE id=NEW.parent_id) THEN RAISE EXCEPTION 'device-group-parent-missing'; END IF;
 IF NEW.parent_id=NEW.id OR EXISTS(SELECT 1 FROM device_group_ancestors WHERE group_id=NEW.parent_id AND ancestor_id=NEW.id) THEN RAISE EXCEPTION 'device-group-cycle'; END IF;
 IF NEW.parent_id IS NOT NULL AND (SELECT coalesce(max(depth),0) FROM device_group_ancestors WHERE group_id=NEW.parent_id)+1+(SELECT coalesce(max(depth),0) FROM device_group_ancestors WHERE ancestor_id=NEW.id)>4 THEN RAISE EXCEPTION 'device-group-depth-limit'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_groups_update_membership_paths()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS (
  SELECT 1 FROM device_group_members subtree_member
  JOIN device_group_ancestors subtree ON subtree.group_id=subtree_member.group_id AND subtree.ancestor_id=OLD.id
  JOIN device_group_members new_ancestor_member ON new_ancestor_member.server_id=subtree_member.server_id
  JOIN device_group_ancestors new_ancestors ON new_ancestors.group_id=NEW.parent_id AND new_ancestors.ancestor_id=new_ancestor_member.group_id
 ) THEN RAISE EXCEPTION 'device-group-membership-path-conflict'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.device_groups_update_paths()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 DELETE FROM device_group_paths
  WHERE group_id IN (SELECT group_id FROM device_group_paths WHERE ancestor_id=NEW.id)
   AND ancestor_id IN (SELECT ancestor_id FROM device_group_paths WHERE group_id=NEW.id AND depth>0);
 INSERT INTO device_group_paths(group_id,ancestor_id,depth)
  SELECT subtree.group_id,ancestor.ancestor_id,subtree.depth+ancestor.depth+1
  FROM device_group_paths subtree JOIN device_group_paths ancestor ON ancestor.group_id=NEW.parent_id
  WHERE subtree.ancestor_id=NEW.id;
 RETURN NULL;
END $function$;

