CREATE OR REPLACE FUNCTION public.rbac_roles_insert_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM rbac_roles existing_role WHERE existing_role.id=NEW.id) THEN
  IF NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id) THEN RAISE EXCEPTION 'customer-missing'; END IF;
  IF EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id AND status='disabled') THEN RAISE EXCEPTION 'customer-disabled'; END IF;
 END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.rbac_roles_insert_customer_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN NEW.permissions IS JSON ARRAY THEN NEW.permissions::jsonb ELSE '[]'::jsonb END) customer_right(value) WHERE customer_right.value='*' OR substring(customer_right.value from 1 for 7)='portal.') THEN
  RAISE EXCEPTION 'customer-role-permissions';
 END IF;
 RETURN NEW;
END $function$;

