CREATE OR REPLACE FUNCTION public.role_assignments_insert_customer()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM rbac_roles customer_role WHERE customer_role.id=NEW.role_id AND customer_role.customer_id IS NOT NULL AND NOT (
  (NEW.scope_type='devicegroup' AND EXISTS(SELECT 1 FROM device_groups target WHERE target.id=NEW.scope_id AND target.customer_id=customer_role.customer_id))
  OR (NEW.scope_type='device' AND EXISTS(SELECT 1 FROM servers target WHERE target.id=NEW.scope_id AND target.customer_id=customer_role.customer_id)))) THEN
  RAISE EXCEPTION 'customer-role-scope';
 END IF;
 RETURN NEW;
END $function$;

