CREATE OR REPLACE FUNCTION public.user_groups_delete_customer_assignments()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 DELETE FROM customer_assignments WHERE principal_type='group' AND principal_id=OLD.id;
 RETURN NULL;
END $function$;

